// src/components/pages/Home.js
import React from "react";
import { motion } from "framer-motion";
import { useNavigate } from "react-router-dom";
import PageWrapper from "../PageWrapper";

const Home = () => {
  const navigate = useNavigate();

  return (
    <PageWrapper>
      <div className="flex flex-col items-center justify-center min-h-screen px-6 bg-gray-50">
        <motion.h1
          initial={{ y: -30, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          transition={{ duration: 0.7 }}
          className="text-4xl md:text-5xl font-extrabold text-gray-900 mb-10"
          style={{ fontFamily: "'Poppins', 'Inter', sans-serif" }}
        >
          Welcome Back!
        </motion.h1>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-10 w-full max-w-4xl">
          {/* Interview Card */}
          <motion.div
            whileHover={{ scale: 1.05, boxShadow: "0 8px 25px rgba(0,0,0,0.15)" }}
            className="cursor-pointer bg-white rounded-2xl shadow-md p-10 flex flex-col items-center justify-center transition-all"
            onClick={() => navigate("/interview")}
          >
            <h2 className="text-2xl font-bold text-gray-800 mb-4">Interview</h2>
            <p className="text-gray-600 text-center">
              Record your mock interview and get AI-powered feedback.
            </p>
          </motion.div>

          {/* Practice Questions Card */}
          <motion.div
            whileHover={{ scale: 1.05, boxShadow: "0 8px 25px rgba(0,0,0,0.15)" }}
            className="cursor-pointer bg-white rounded-2xl shadow-md p-10 flex flex-col items-center justify-center transition-all"
            onClick={() => navigate("/practice")}
          >
            <h2 className="text-2xl font-bold text-gray-800 mb-4">Practice Questions</h2>
            <p className="text-gray-600 text-center">
              Practice common interview questions to improve your skills.
            </p>
          </motion.div>
        </div>
      </div>
    </PageWrapper>
  );
};

export default Home;
